def _load_embedded():
    raw = zlib.decompress(base64.b85decode("".join(_EMBEDDED.split())))
    return json.loads(raw.decode("utf-8"))

_SPEC = _load_embedded()


def _outcome_index(mine: int, theirs: int) -> int:
    if mine == C:
        return 0 if theirs == C else 1
    return 2 if theirs == C else 3


def _features(t: int, mine, theirs) -> list[float]:
    if len(mine) != len(theirs):
        raise ValueError("mine and theirs must have the same length")
    if int(t) != len(mine):
        raise ValueError("t must match the pre-step history length")
    t = int(t)
    out = [0.0] * 21
    out[0] = t / 100.0
    out[1] = (100 - t) / 100.0
    for lag in range(1, 5):
        j = 6 + 2 * (lag - 1)
        out[j] = -1.0
        out[j + 1] = -1.0
    if t:
        out[2 + _outcome_index(mine[-1], theirs[-1])] = 1.0
        for lag in range(1, 5):
            j = 6 + 2 * (lag - 1)
            if t >= lag:
                out[j] = float(mine[-lag])
                out[j + 1] = float(theirs[-lag])
        denom = float(max(1, t))
        opp_def = sum(1 for x in theirs if x == D) / denom
        own_def = sum(1 for x in mine if x == D) / denom
        recent = theirs[-10:]
        out[14] = opp_def
        out[15] = own_def
        out[16] = (sum(1 for x in recent if x == D) / len(recent)
                   if recent else 0.0)
        out[17] = own_def - opp_def
        out[18] = sum(1 for a, b in zip(mine, theirs)
                      if a == C and b == C) / denom
        out[19] = sum(1 for a, b in zip(mine, theirs)
                      if a == D and b == D) / denom
    out[20] = 1.0 if t >= 90 else 0.0
    return out


def _sigmoid2(x: float) -> float:
    if x >= 0.0:
        return 1.0 / (1.0 + math.exp(-min(x, 40.0)))
    z = math.exp(max(x, -40.0))
    return z / (1.0 + z)


def _matvec(w, x, b=None):
    out = [sum(a * c for a, c in zip(row, x)) for row in w]
    if b is not None:
        out = [v + bias for v, bias in zip(out, b)]
    return out


def _linear(layer, x):
    w, b = layer
    return _matvec(w, x, b)


class _SelfPlayGRUPolicy:
    def __init__(self, spec: dict, seed: int = 20261026):
        if spec.get("format") != "ipd-selfplay-gru-v1":
            raise ValueError(f"unsupported self-play format: {spec.get('format')}")
        self.n_features = int(spec["n_features"])
        self.hidden = int(spec["hidden"])
        self.layers = int(spec["layers"])
        self.rng = random.Random(seed)
        self.gru = []
        for layer in spec["gru"]:
            self.gru.append((
                [[float(x) for x in row] for row in layer["w_ih"]],
                [float(x) for x in layer["b_ih"]],
                [[float(x) for x in row] for row in layer["w_hh"]],
                [float(x) for x in layer["b_hh"]],
            ))
        self.actor = [
            ([[float(x) for x in row] for row in layer["w"]],
             [float(x) for x in layer["b"]])
            for layer in spec["actor"]
        ]
        self.critic = [
            ([[float(x) for x in row] for row in layer["w"]],
             [float(x) for x in layer["b"]])
            for layer in spec["critic"]
        ]
        self.h = [[0.0] * self.hidden for _ in range(self.layers)]

    def reset(self) -> None:
        self.h = [[0.0] * self.hidden for _ in range(self.layers)]

    def _gru_layer(self, x, h, layer):
        w_ih, b_ih, w_hh, b_hh = layer
        gi = _matvec(w_ih, x, b_ih)
        gh = _matvec(w_hh, h, b_hh)
        n = self.hidden
        r = [_sigmoid2(gi[i] + gh[i]) for i in range(n)]
        z = [_sigmoid2(gi[n + i] + gh[n + i]) for i in range(n)]
        nn = [math.tanh(gi[2 * n + i] + r[i] * gh[2 * n + i])
              for i in range(n)]
        return [(1.0 - z[i]) * nn[i] + z[i] * h[i] for i in range(n)]

    def _forward(self, features):
        if len(features) != self.n_features:
            raise ValueError("feature count mismatch")
        x = [float(v) for v in features]
        new_h = []
        for i, layer in enumerate(self.gru):
            x = self._gru_layer(x, self.h[i], layer)
            new_h.append(x)
        self.h = new_h
        h = x
        for layer in self.actor[:-1]:
            h = [math.tanh(v) for v in _linear(layer, h)]
        logit = _linear(self.actor[-1], h)[0]
        c = x
        for layer in self.critic[:-1]:
            c = [math.tanh(v) for v in _linear(layer, c)]
        value = _linear(self.critic[-1], c)[0]
        return logit, value

    def act(self, t, mine, theirs):
        logit, _ = self._forward(_features(t, mine, theirs))
        return D if self.rng.random() < _sigmoid2(logit) else C


class SelfPlayGRU(Player):
    """Axelrod Player around the self-play GRU policy."""

    name = "SelfPlay-GRU"
    classifier = {
        "memory_depth": float("inf"),
        "stochastic": True,
        "long_run_time": False,
        "inspects_source": False,
        "manipulates_source": False,
        "manipulates_state": False,
    }

    def __init__(self, seed: int = 20261026, mode: str = "sample",
                 name: str | None = None):
        super().__init__()
        _require_sample(mode, "SelfPlay-GRU")
        self.seed = int(seed)
        self.mode = mode
        if name is not None:
            self.name = str(name)
        self.policy = _SelfPlayGRUPolicy(_SPEC, self.seed)

    def strategy(self, opponent: Player) -> Action:
        mine, theirs = _histories(self, opponent)
        action = self.policy.act(len(theirs), mine, theirs)
        return A_D if action == D else A_C

    def __repr__(self) -> str:
        return self.name


def build(seed: int = 20261026, mode: str = "sample",
          name: str | None = None, **_: object) -> SelfPlayGRU:
    return SelfPlayGRU(seed=seed, mode=mode, name=name)


__all__ = ["SelfPlayGRU", "build", "GAME"]


if __name__ == "__main__":
    import axelrod as axl

    for opponent in (axl.Cooperator(), axl.Defector(), axl.TitForTat(),
                     axl.Grudger()):
        match = axl.Match((SelfPlayGRU(), opponent), turns=100, game=GAME)
        match.play()
        scores = match.final_score()
        print(f"{SelfPlayGRU.name:12} vs {opponent.name:15} "
              f"{scores[0]:4d} - {scores[1]:4d}")
